```cpp
#include <bits/stdc++.h>
using namespace std;
int a[105][105];
int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> a[i][j];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (j > 0) cout << ' ';
            cout << a[i][j];
        }
        cout << endl;
    }
    return 0;
}
```

参考代码：

```cpp
#include <bits/stdc++.h>
using namespace std;
int a[105][105];
int main() {
    int n, m, k;
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> a[i][j];
    cin >> k;
    int cnt = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (a[i][j] > k) cnt++;
    cout << cnt << endl;
    return 0;
}
```

参考代码：

```cpp
#include <bits/stdc++.h>
using namespace std;
int a[105];
int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    bool first = true;
    for (int i = 0; i < n; i++) {
        if (a[i] % 2 == 0) {
            if (!first) cout << ' ';
            cout << a[i];
            first = false;
        }
    }
    if (first) cout << 0;
    cout << endl;
    return 0;
}
```
